import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Business Email FAQ","description":"","frontmatter":{"title":"Business Email FAQ"},"headers":[],"relativePath":"operations-knowledge-base/ssl/business-email-faq.md","filePath":"operations-knowledge-base/ssl/business-email-faq.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/ssl/business-email-faq.md"};function n(o,e,l,d,h,m){return t(),r("div",null,[...e[0]||(e[0]=[i('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This article answers common questions about login, administration, and configuration for RAKsmart enterprise email.</p><h2 id="_1-are-mail-servers-in-china-or-the-united-states" tabindex="-1">1. Are mail servers in China or the United States? <a class="header-anchor" href="#_1-are-mail-servers-in-china-or-the-united-states" aria-label="Permalink to &quot;1. Are mail servers in China or the United States?&quot;">​</a></h2><p>Servers are distributed globally. Access from overseas uses overseas nodes; access from China uses domestic nodes to improve delivery speed and stability in each region.</p><h2 id="_2-is-there-a-separate-administrator-account" tabindex="-1">2. Is there a separate administrator account? <a class="header-anchor" href="#_2-is-there-a-separate-administrator-account" aria-label="Permalink to &quot;2. Is there a separate administrator account?&quot;">​</a></h2><p>Yes. After provisioning, you receive administrator credentials on the platform.</p><ul><li>Login URL: <a href="https://mail.chengmail.cn/" target="_blank" rel="noreferrer">https://mail.chengmail.cn</a></li><li>The page opens in user login mode by default</li><li>Click Switch to administrator login on the right side of the welcome message</li><li>Log in with the administrator account</li></ul><h2 id="_3-i-forgot-the-enterprise-email-administrator-password" tabindex="-1">3. I forgot the enterprise email administrator password <a class="header-anchor" href="#_3-i-forgot-the-enterprise-email-administrator-password" aria-label="Permalink to &quot;3. I forgot the enterprise email administrator password&quot;">​</a></h2><p>Administrator passwords can only be reset from the backend. Self-service reset is not available. Open a support ticket with your domain or email product order details.</p><h2 id="_4-enterprise-email-help-center" tabindex="-1">4. Enterprise email help center <a class="header-anchor" href="#_4-enterprise-email-help-center" aria-label="Permalink to &quot;4. Enterprise email help center&quot;">​</a></h2><ul><li><a href="https://mail.chengmail.cn/help/index.php?_m=articleview&amp;_a=view" target="_blank" rel="noreferrer">https://mail.chengmail.cn/help/index.php?_m=articleview&amp;_a=view</a></li><li><a href="https://mail.chengmail.cn/help/index.php?_m=articleview&amp;_a=view&amp;category_id=044f972f81a3be258c2c35e8ae6ee6d8&amp;lang=zh_CN" target="_blank" rel="noreferrer">Chinese user manual</a></li></ul><h2 id="_5-how-do-i-set-up-smtp-what-about-mx-cname-and-txt-records" tabindex="-1">5. How do I set up SMTP? What about MX, CNAME, and TXT records? <a class="header-anchor" href="#_5-how-do-i-set-up-smtp-what-about-mx-cname-and-txt-records" aria-label="Permalink to &quot;5. How do I set up SMTP? What about MX, CNAME, and TXT records?&quot;">​</a></h2><p>Log in to the enterprise email admin panel and open Domain management or Mailbox settings. The system shows the records required for your domain:</p><table tabindex="0"><thead><tr><th>Record type</th><th>Purpose</th></tr></thead><tbody><tr><td>MX</td><td>Mail routing</td></tr><tr><td>TXT (SPF)</td><td>Anti-spoofing and deliverability</td></tr><tr><td>CNAME</td><td>Required for some features, as shown in the panel</td></tr><tr><td>SMTP</td><td>Outbound server and port, as shown in the panel</td></tr></tbody></table><p>Values are domain-specific. Use what the admin panel displays. If you cannot find them, open a ticket with your domain name.</p><h2 id="_6-how-do-i-create-and-manage-user-mailboxes" tabindex="-1">6. How do I create and manage user mailboxes? <a class="header-anchor" href="#_6-how-do-i-create-and-manage-user-mailboxes" aria-label="Permalink to &quot;6. How do I create and manage user mailboxes?&quot;">​</a></h2><p>After logging in as administrator at <a href="https://mail.chengmail.cn/" target="_blank" rel="noreferrer">mail.chengmail.cn</a>, you can create or delete mailboxes, assign quotas, and configure aliases and forwarding. See the <a href="https://mail.chengmail.cn/help/index.php?_m=articleview&amp;_a=view&amp;category_id=044f972f81a3be258c2c35e8ae6ee6d8&amp;lang=zh_CN" target="_blank" rel="noreferrer">enterprise email help center</a> for details.</p><h2 id="_7-technical-support" tabindex="-1">7. Technical support <a class="header-anchor" href="#_7-technical-support" aria-label="Permalink to &quot;7. Technical support&quot;">​</a></h2><p>Open a support ticket from the client area with your domain, a description of the issue, and steps already tried with screenshots.</p>',19)])])}const u=a(s,[["render",n]]);export{c as __pageData,u as default};
